import Flutter
import WorkoutKit
import XCTest

@testable import flutter_workoutkit

/// Regression tests over larger corpora: workouts serialized by 0.0.11, every
/// sample, and a seeded random corpus of ~300 workouts generated by
/// `test/support/random_workouts.dart`.
final class RegressionTests: XCTestCase {
    private func plan(_ json: Any) throws -> WorkoutPlan {
        try WorkoutPlanBuilder.plan(from: json)
    }

    private func dictionary(_ name: String) throws -> [String: [String: Any]] {
        try XCTUnwrap(Fixtures.load(name) as? [String: [String: Any]])
    }

    // MARK: 0.0.11 compatibility

    func testWorkoutsSerializedBy0011StillBuild() throws {
        let legacy = try dictionary("legacy_0.0.11/samples.json")
        let current = try dictionary("samples.json")
        XCTAssertEqual(legacy.count, 11)
        for (name, json) in legacy {
            let built = try plan(json)
            if name == "sampleSingleGoalEnergyWorkout" {
                // The sample changed in 0.1.0; the old JSON must still mean 1000 small calories.
                guard case let .goal(workout) = built.workout else { return XCTFail(name) }
                XCTAssertEqual(workout.goal, .energy(1000, .calories))
                continue
            }
            XCTAssertEqual(built.workout, try plan(XCTUnwrap(current[name])).workout, name)
        }
    }

    func testAlertsSerializedBy0011StillBuild() throws {
        let current = try Fixtures.array("alerts.json")
        for json in try Fixtures.array("legacy_0.0.11/alerts.json") {
            let type = try XCTUnwrap(json["type"] as? String)
            let match = try XCTUnwrap(current.first { $0["type"] as? String == type })
            XCTAssertEqual(
                AnyHashable(try WorkoutBuilder.workoutAlert(JSONReader(json))),
                AnyHashable(try WorkoutBuilder.workoutAlert(JSONReader(match))),
                type
            )
        }
    }

    // MARK: Samples

    func testEverySampleBuildsValidatesAndRoundTrips() throws {
        let samples = try dictionary("samples.json")
        XCTAssertGreaterThanOrEqual(samples.count, 13)
        for (name, json) in samples {
            if name == "samplePoolSwimIntervals", #unavailable(iOS 18.0) {
                // Pool swim goals need iOS 18; older runtimes must report it.
                XCTAssertEqual(WorkoutValidator.issues(for: json).map(\.code), [.unsupportedOS], name)
                continue
            }
            let built = try plan(json)
            XCTAssertEqual(WorkoutValidator.issues(for: json), [], name)
            XCTAssertEqual(try plan(WorkoutPlanSerializer.json(built)), built, name)
            XCTAssertEqual(try WorkoutPlan(from: built.dataRepresentation), built, name)
        }
    }

    // MARK: Random corpus

    func testRandomCorpusNeverCrashesAndRoundTrips() throws {
        let corpus = try XCTUnwrap(Fixtures.load("random_workouts.json") as? [[String: Any]])
        XCTAssertGreaterThanOrEqual(corpus.count, 300)

        var built = 0
        var unsupported = 0
        for (index, json) in corpus.enumerated() {
            let label = "random_workouts.json[\(index)]"
            let plan: WorkoutPlan
            do {
                // WorkoutKit traps on unsupported workouts; reaching the next
                // line for every entry is the main assertion of this test.
                plan = try self.plan(json)
            } catch let error as WorkoutkitError {
                // Dart produced this JSON, so it must never be malformed.
                XCTAssertTrue(
                    ["UNSUPPORTED_WORKOUT", "UNSUPPORTED_OS"].contains(error.code),
                    "\(label): \(error)"
                )
                XCTAssertFalse(WorkoutValidator.issues(for: json).isEmpty, label)
                unsupported += 1
                continue
            }
            built += 1
            XCTAssertEqual(WorkoutValidator.issues(for: json), [], label)
            XCTAssertEqual(try self.plan(WorkoutPlanSerializer.json(plan)), plan, label)
            XCTAssertEqual(try WorkoutPlan(from: plan.dataRepresentation), plan, label)
            if let id = json["id"] as? String {
                XCTAssertEqual(plan.id.uuidString, id, label)
            }
        }
        // The corpus must exercise both paths to be meaningful.
        XCTAssertGreaterThan(built, 50)
        XCTAssertGreaterThan(unsupported, 50)
    }

    // MARK: Older iOS versions (simulated)

    func testOnIOS17StepNamesAreDropped() throws {
        let onIOS17 = try onIOS17_0 { try plan(Fixtures.object("custom_workout.json")).workout }
        guard case let .custom(workout) = onIOS17 else {
            return XCTFail("expected a custom workout")
        }
        if #available(iOS 18.0, *) {
            XCTAssertNil(workout.warmup?.displayName)
        }
        guard case let .custom(current) = try plan(Fixtures.object("custom_workout.json")).workout else {
            return XCTFail("expected a custom workout")
        }
        if #available(iOS 18.0, *) {
            XCTAssertEqual(current.warmup?.displayName, "Easy warmup")
        }
    }

    func testOnIOS17PoolSwimGoalsAreReportedNotCrashed() throws {
        let json = try Fixtures.object("pool_swim_workout.json")
        try onIOS17_0 {
            XCTAssertThrowsError(try plan(json)) { error in
                XCTAssertEqual((error as? WorkoutkitError)?.code, "UNSUPPORTED_OS")
            }
            XCTAssertEqual(WorkoutValidator.issues(for: json).count, 1)

            let messenger = MockBinaryMessenger()
            let bridge = WorkoutPreviewBridge(
                frame: .zero, viewIdentifier: 7, arguments: ["workoutJson": json], messenger: messenger
            )
            withExtendedLifetime(bridge) {
                let error = messenger.invoke("workout_preview_button_7", "getBuildError") as? [String: String]
                XCTAssertEqual(error?["code"], "UNSUPPORTED_OS")
            }
        }
        // Outside the scope the real OS features apply again.
        if #available(iOS 18.0, *) { XCTAssertNoThrow(try plan(json)) }
    }

    func testOnIOS17_0PowerAlertsFallBackToCurrentMetric() throws {
        let json: [String: Any] = ["type": "powerRange", "lowerBound": 200, "upperBound": 250, "metric": "average"]
        let alert = try onIOS17_0 { try WorkoutBuilder.workoutAlert(JSONReader(json)) }
        XCTAssertEqual(AnyHashable(alert), AnyHashable(PowerRangeAlert.power(200...250, unit: .watts)))
    }

    func testOnIOS17EverySampleExceptPoolSwimBuilds() throws {
        let samples = try dictionary("samples.json")
        try onIOS17_0 {
            for (name, json) in samples {
                if name == "samplePoolSwimIntervals" {
                    XCTAssertThrowsError(try plan(json), name)
                } else {
                    XCTAssertNoThrow(try plan(json), name)
                }
            }
        }
    }
}
